create function pg_temp.source_engage_doc()returns jsonb language sql immutable as $fn$select $doc${"schemaVersion":1,"artboard":{"width":1920,"height":1080,"orientation":"landscape","background":{"kind":"solid","color":"#FAFAF7"},"safeArea":{"top":64,"right":64,"bottom":64,"left":64}},"motion":{"enabled":true,"durationMs":5000,"fps":30},"elements":[],"syncPresentation":{"schemaVersion":1,"rendererVersion":"sync-v1","sourceRevision":"8b1fdf1f8637dda23d48ecdaf08e0e5978e2707a","family":"engage","orientation":"landscape","theme":"fieldflow","name":"Publieksactie","club":{"name":"Source Engage A","tagline":""},"title":"LAAT DE CLUB MEEDOEN","headline":"","body":"","subtitle":"","topLabel":"CLUB TV","footer":"","footerRight":"","rows":[],"rowsPerPage":4,"ownRowIndexes":[],"category":"","subline":"","lineup":[],"news":[],"imageCaption":"","poll":{"id":"20000000-0000-4000-8000-000000226181","title":"Wie was de beste?","status":"live","visibility":"after_vote","options":[{"id":"30000000-0000-4000-8000-000000226181","label":"Eigen speler A","votes":0},{"id":"30000000-0000-4000-8000-000000226182","label":"Eigen speler B","votes":0}]},"state":"ready","style":{"motion":"rustig","background":"stadium","backgroundPosition":"center","font":"Inter, sans-serif","fontChanged":false,"accent":"#1763ed","alignment":"left","scale":100,"safeMargin":5,"showLogo":true,"showFooter":true}},"metadata":{"fontRegistryVersion":"2026-09-09.1","tenantBrandApplied":false}}$doc$::jsonb$fn$;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000226181',true);
select lives_ok($$select public.create_studio_project_v1(p_tenant_id=>'10000000-0000-4000-8000-000000226181',p_name=>'Eigen Source-publieksvraag',p_project_kind=>'design',p_orientation=>'landscape',p_document=>pg_temp.source_engage_doc(),p_referenced_asset_ids=>'{}'::uuid[],p_idempotency_key=>'40000000-0000-4000-8000-000000226181')$$,'a real owner stores the complete own Source campaign through the existing Studio writer');
select throws_ok($$select public.create_studio_project_v1(p_tenant_id=>'10000000-0000-4000-8000-000000226181',p_name=>'Onbekende vraag',p_project_kind=>'design',p_orientation=>'landscape',p_document=>jsonb_set(pg_temp.source_engage_doc(),'{syncPresentation,poll,id}','"20000000-0000-4000-8000-000000226182"'),p_referenced_asset_ids=>'{}'::uuid[],p_idempotency_key=>'40000000-0000-4000-8000-000000226182')$$,'42501',null,'a public ID from B cannot become a tenant A Source campaign');
select throws_ok($$select public.create_studio_project_v1(p_tenant_id=>'10000000-0000-4000-8000-000000226181',p_name=>'Onbekende keuze',p_project_kind=>'design',p_orientation=>'landscape',p_document=>jsonb_set(pg_temp.source_engage_doc(),'{syncPresentation,poll,options,0,id}','"30000000-0000-4000-8000-000000226183"'),p_referenced_asset_ids=>'{}'::uuid[],p_idempotency_key=>'40000000-0000-4000-8000-000000226183')$$,'23514',null,'a Source campaign cannot include a foreign option');
select throws_ok($$select public.create_studio_project_v1(p_tenant_id=>'10000000-0000-4000-8000-000000226181',p_name=>'Private resultaten',p_project_kind=>'design',p_orientation=>'landscape',p_document=>jsonb_set(jsonb_set(pg_temp.source_engage_doc(),'{syncPresentation,poll,visibility}','"live"'),'{syncPresentation,poll,options,0,votes}','8'),p_referenced_asset_ids=>'{}'::uuid[],p_idempotency_key=>'40000000-0000-4000-8000-000000226184')$$,'23514',null,'an author cannot turn nonpublic results into an offline Source card');
select is((select count(*)from public.studio_projects where tenant_id='10000000-0000-4000-8000-000000226181'),1::bigint,'rejected Source bindings create no extra projects');
reset role;
update public.tenant_feature_flags set enabled=false where tenant_id='10000000-0000-4000-8000-000000226181'and flag_key='engage';
set local role authenticated;
select throws_ok($$select public.create_studio_project_v1(p_tenant_id=>'10000000-0000-4000-8000-000000226181',p_name=>'Gesloten vrijgave',p_project_kind=>'design',p_orientation=>'landscape',p_document=>pg_temp.source_engage_doc(),p_referenced_asset_ids=>'{}'::uuid[],p_idempotency_key=>'40000000-0000-4000-8000-000000226185')$$,'42501',null,'the existing Engage rollout cannot be bypassed with a Source document');
reset role;
select is(has_function_privilege('authenticated','private.assert_sync_slide_v1(uuid,jsonb)','execute'),false,'the combined Source admission remains private');
select is(has_function_privilege('authenticated','private.assert_sync_slide_before_engage_v1(uuid,jsonb)','execute'),false,'the prior validator is not an authoring bypass');
select is(has_function_privilege('authenticated','private.assert_sync_engage_release_binding_v1()','execute'),false,'the release binding validator is not a public writer');
select *from finish();rollback;
